<template>
  <main class="doc-view" :style="documentStyle">
    <header class="doc-toolbar">
      <button title="返回资源库" @click="router.push({ name: 'resources' })">←</button><span class="toolbar-title">讲解文档</span>
      <div><button :class="{ active: resource?.favorited }" title="收藏" :disabled="!resource" @click="favorite">☆</button><button title="重炼一份" :disabled="!resource || reforging" @click="reforge">↻</button></div>
    </header>
    <aside v-if="toc.length" class="toc" aria-label="目录"><button v-for="item in toc" :key="item.id" :class="{ active: activeId === item.id, level2: item.level === 2, level3: item.level === 3 }" @click="scrollTo(item.id)">{{ item.text }}</button></aside>
    <section class="document-shell"><article class="document">
      <header class="document-title"><p class="eyebrow">药案讲解</p><h1>{{ resource?.title || '正在整理讲解' }}</h1><div class="document-meta"><span>本草辨析</span><span>{{ createdAt }}</span></div></header>
      <p v-if="streaming" class="generation-state">正逐段入卷</p>
      <section v-for="(block, index) in blocks" :key="`${index}-${block.text}`" class="block" :class="[`block-${block.type}`, { 'is-revealing': animated.has(index) }]" :style="{ animationDelay: `${Math.min(index, 6) * stage4Visual.document.blockStaggerMs}ms` }" @animationend="finishReveal(index)">
        <template v-if="block.type === 'heading'"><component :is="headingTag(block.text)" :id="headingId(index)">{{ headingText(block.text) }}</component></template>
        <template v-else-if="block.type === 'bullet'"><ul><li v-for="line in listItems(block.text)" :key="line"><InlineText :text="line" @citation="openCitation" /></li></ul></template>
        <template v-else-if="block.type === 'table'"><div class="table-wrap" :class="{ skeleton: !tableRows(block.text).length }"><table v-if="tableRows(block.text).length"><thead><tr><th v-for="cell in tableRows(block.text)[0]" :key="cell">{{ cell }}</th></tr></thead><tbody><tr v-for="(row, rowIndex) in tableRows(block.text).slice(1)" :key="rowIndex"><td v-for="(cell, cellIndex) in row" :key="cellIndex"><InlineText :text="cell" @citation="openCitation" /></td></tr></tbody></table><p v-else><InlineText :text="block.text" @citation="openCitation" /></p></div></template>
        <template v-else-if="block.type === 'callout'"><div class="callout"><span>注</span><InlineText :text="block.text" @citation="openCitation" /></div></template>
        <template v-else-if="block.type === 'quote'"><blockquote><InlineText :text="block.text" @citation="openCitation" /><cite>教材摘录</cite></blockquote></template>
        <p v-else><InlineText :text="block.text" @citation="openCitation" /></p>
      </section>
      <details v-if="resource?.notes" class="alchemy-notes"><summary>炼丹手记</summary><div><i class="pin"/><i class="seal">录</i>{{ resource.notes }}</div></details>
    </article></section>
    <nav class="study-actions" aria-label="学完这篇"><span>学完这篇</span><button @click="router.push({ name: 'quiz' })">去练一练</button><button @click="router.push({ name: 'atlas' })">看图谱</button><button @click="router.push({ name: 'path' })">回脉络图</button></nav>
    <Transition name="citation"><aside v-if="selectedSource" class="citation-panel"><button title="关闭引用" @click="selectedSource = null">×</button><p>出处</p><h2>{{ sourceValue(selectedSource, ['出处', 'source', 'title']) || '未标注出处' }}</h2><p>原文摘录</p><blockquote><small>教材摘录</small>{{ sourceValue(selectedSource, ['原文摘录', 'quote']) || '暂无原文摘录' }}</blockquote><p>定位</p><strong>{{ sourceValue(selectedSource, ['定位', 'ref']) || '暂无定位信息' }}</strong></aside></Transition>
  </main>
</template>

<script setup lang="ts">
import { computed, defineComponent, h, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { stage4Visual } from '../config/stage4Visual'
import { createResourceTask, getResource, streamResourceTask, toggleResourceFavorite } from '../services/resourceApi'
import { parseMarkdownTable, type ResourceDocBlock, type ResourceItem, type ResourceSource } from '../types/resource'

const InlineText = defineComponent({
  props: { text: { type: String, required: true } }, emits: ['citation'],
  setup(props, { emit }) {
    const inline = (part: string) => part.split(/(\*\*[^*]+\*\*)/g).map(piece => piece.startsWith('**') ? h('strong', piece.slice(2, -2)) : piece)
    return () => h('span', props.text.split(/(\[\d+\])/g).flatMap(part => {
      const match = /^\[(\d+)\]$/.exec(part)
      return match ? [h('button', { class: 'citation-mark', onClick: () => emit('citation', Number(match[1])) }, `[${Number(match[1]) + 1}]`)] : inline(part)
    }))
  },
})

const route = useRoute(); const router = useRouter(); const resource = ref<ResourceItem>(); const blocks = ref<ResourceDocBlock[]>([]); const animated = ref(new Set<number>()); const selectedSource = ref<ResourceSource | null>(null); const activeId = ref(''); const streaming = ref(false); const reforging = ref(false); const observer = ref<IntersectionObserver>(); let controller: AbortController | undefined; let userScrolled = false
const documentStyle = computed(() => ({ '--doc-line-height': String(stage4Visual.document.readingLineHeight), '--doc-measure': stage4Visual.document.measure, '--doc-paragraph-gap': stage4Visual.document.paragraphGap, '--doc-reveal-duration': `${stage4Visual.document.blockRevealMs}ms`, '--doc-reveal-distance': stage4Visual.document.blockRevealDistance, '--doc-citation-duration': `${stage4Visual.document.citationTransitionMs}ms`, '--doc-action-blur': stage4Visual.document.actionBarBlur }))
const createdAt = computed(() => resource.value?.created_at ? new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'short', day: 'numeric' }).format(new Date(resource.value.created_at)) : '生成中')
const mockResource: ResourceItem = { id: 'mock-doc', node_id: 'd01', type: 'doc', title: '麻黄 · 性味归经与功效', status: 'ready', created_at: new Date().toISOString(), favorited: false, sources: [{ '出处': '《本草纲目》', '原文摘录': '麻黄，发汗解表。', '定位': '草部' }], notes: '依次完成本草检索、结构编排与溯源校验后封存。', content: { blocks: [{ type: 'heading', text: '# 麻黄的核心定位' }, { type: 'paragraph', text: '麻黄以发汗解表、宣肺平喘、利水消肿见长 [0]。' }, { type: 'callout', text: '表实无汗是辨识使用情境的关键。' }, { type: 'table', text: '| 维度 | 要点 |\n| --- | --- |\n| 性味 | 辛、微苦，温 |\n| 归经 | 肺、膀胱经 |' }] } }
const toc = computed(() => blocks.value.map((block, index) => ({ id: headingId(index), text: headingText(block.text), level: headingLevel(block.text) })).filter((_, index) => blocks.value[index].type === 'heading'))
const headingLevel = (text: string) => Math.min(3, Math.max(1, (text.match(/^#{1,3}/)?.[0].length || 1)))
const headingTag = (text: string) => `h${headingLevel(text)}`; const headingText = (text: string) => text.replace(/^#{1,3}\s*/, ''); const headingId = (index: number) => `doc-heading-${index}`; const listItems = (text: string) => text.split(/\r?\n/).map(line => line.replace(/^[-*]\s*/, '').trim()).filter(Boolean); const tableRows = (text: string) => parseMarkdownTable(text)
const sourceValue = (source: ResourceSource, keys: string[]) => keys.map(key => source[key]).find(Boolean)
const openCitation = (index: number) => { selectedSource.value = resource.value?.sources?.[index] ?? null }
const favorite = async () => { if (resource.value) resource.value = await toggleResourceFavorite(resource.value.id) }
const reforge = async () => { if (!resource.value) return; reforging.value = true; try { const task = await createResourceTask(resource.value.node_id, resource.value.type); router.push({ name: 'resource-detail', params: { id: resource.value.id }, query: { task: task.task_id } }) } finally { reforging.value = false } }
const reveal = async (block: ResourceDocBlock) => { blocks.value.push(block); const index = blocks.value.length - 1; animated.value = new Set([...animated.value, index]); await nextTick(); if (!userScrolled) window.scrollTo({ top: document.documentElement.scrollHeight, behavior: 'smooth' }) }
const finishReveal = (index: number) => { if (!animated.value.has(index)) return; const next = new Set(animated.value); next.delete(index); animated.value = next }
const finishStreaming = () => window.setTimeout(() => { animated.value = new Set(); streaming.value = false }, stage4Visual.document.blockRevealMs + stage4Visual.document.blockStaggerMs * 6)
const load = async () => { controller?.abort(); blocks.value = []; animated.value = new Set(); userScrolled = false; const id = String(route.params.id); const task = typeof route.query.task === 'string' ? route.query.task : ''; try { resource.value = id === 'mock-doc' ? mockResource : await getResource(id) } catch { resource.value = mockResource }; if (task && id === 'mock-doc') { streaming.value = true; const demoBlocks = (mockResource.content?.blocks as ResourceDocBlock[]) || []; for (const block of demoBlocks) { await new Promise(resolve => window.setTimeout(resolve, 420)); await reveal(block) } finishStreaming() } else if (task) { streaming.value = true; controller = new AbortController(); await streamResourceTask(task, event => { if (event.event === 'block' && event.payload.block) void reveal(event.payload.block); if (event.event === 'done') finishStreaming(); if (event.event === 'error') streaming.value = false }, { signal: controller.signal, onConnection: () => undefined }); if (!blocks.value.length) blocks.value = ((resource.value.content?.blocks as ResourceDocBlock[] | undefined) || []) } else blocks.value = ((resource.value?.content?.blocks as ResourceDocBlock[] | undefined) || []) }
const scrollTo = (id: string) => document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' })
onMounted(() => { window.addEventListener('wheel', () => { userScrolled = true }, { passive: true }); observer.value = new IntersectionObserver(entries => { const visible = entries.filter(entry => entry.isIntersecting).sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0]; if (visible) activeId.value = visible.target.id }, { rootMargin: '-18% 0px -68%' }); void load() })
watch(blocks, async () => { await nextTick(); document.querySelectorAll<HTMLElement>('[id^="doc-heading-"]').forEach(element => observer.value?.observe(element)) }, { deep: true }); watch(() => route.fullPath, () => void load()); onBeforeUnmount(() => controller?.abort())
</script>

<style scoped lang="scss">
