.doc-toolbar button{width:32px;height:32px;border:1px solid transparent;border-radius:var(--qh-radius-stage);color:var(--qh-text-muted);background:transparent;font-size:18px;cursor:pointer}.doc-toolbar button:hover,.doc-toolbar button.active{border-color:var(--qh-color-jade-line);color:var(--qh-color-jade);background:var(--qh-color-jade-wash)}.toolbar-title{font-size:13px;color:var(--qh-text-muted)}
