.document h1,.document h2,.document h3{font-family:var(--qh-font-reading);color:var(--qh-color-cream)}.document h1{margin:0 0 var(--qh-space-4);font-size:38px;font-weight:700;line-height:1.28}.document h2{position:relative;margin:58px 0 var(--qh-space-4);padding-left:var(--qh-space-4);font-size:26px;line-height:1.35}.document h2:before{position:absolute;top:.18em;bottom:.2em;left:0;width:3px;background:var(--qh-color-jade);content:''}.document h3{margin:38px 0 var(--qh-space-3);font-size:20px;font-weight:650;line-height:1.45}
.eyebrow,.generation-state{margin:0 0 var(--qh-space-3);color:var(--qh-color-jade);font-size:12px;letter-spacing:1px}.generation-state{color:var(--qh-color-gold)}.document-meta{display:flex;gap:var(--qh-space-3);color:var(--qh-text-muted);font-size:12px}.document-meta span+span:before{margin-right:var(--qh-space-3);color:var(--qh-border);content:'/' }
.block{opacity:1}.block.is-revealing{animation:block-in var(--doc-reveal-duration) ease-out both}.block p,.block li,.table-wrap{font-size:16px;line-height:var(--doc-line-height)}.block p{margin:0 0 var(--doc-paragraph-gap)}.block ul{margin:0 0 var(--doc-paragraph-gap);padding-left:var(--qh-space-6)}.block li+li{margin-top:var(--qh-space-2)}.block :deep(strong){color:var(--qh-color-jade);font-weight:650}
.callout{display:grid;grid-template-columns:32px 1fr;gap:var(--qh-space-3);margin:28px 0;padding:var(--qh-space-4) var(--qh-space-5);border-left:2px solid var(--qh-color-gold);background:var(--qh-color-jade-wash);line-height:var(--doc-line-height)}.callout span{font-family:var(--qh-font-reading);color:var(--qh-color-gold)}
.block blockquote{margin:28px 0;padding:4px 0 4px var(--qh-space-5);border-left:2px solid var(--qh-color-gold);color:var(--qh-text-soft);line-height:var(--doc-line-height)}.block blockquote cite{display:block;margin-top:var(--qh-space-2);color:var(--qh-text-muted);font-size:12px;font-style:normal}
.table-wrap{margin:28px 0;overflow:auto;border:1px solid var(--qh-border);border-radius:var(--qh-radius-stage);background:var(--qh-color-night-raised)}.table-wrap.skeleton{height:115px;background:repeating-linear-gradient(180deg,transparent 0 35px,var(--qh-border) 36px 37px)}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:var(--qh-space-3) var(--qh-space-4);border-bottom:1px solid var(--qh-border)}th{border-bottom-color:var(--qh-color-jade-line);color:var(--qh-color-jade);background:var(--qh-color-jade-wash);font-weight:650}tbody tr:nth-child(even){background:color-mix(in srgb,var(--qh-color-cream) 4%,transparent)}
.citation-mark{display:inline;padding:0 2px;border:0;color:var(--qh-color-jade);background:transparent;font:inherit;font-size:.78em;cursor:pointer;transition:transform var(--doc-citation-duration)}.citation-mark:hover{transform:scale(1.13)}
.toc{position:fixed;top:116px;left:max(var(--qh-space-6),calc(50% - 560px));z-index:2;display:grid;width:165px;gap:5px}.toc button{padding:3px 0;border:0;color:var(--qh-text-muted);background:transparent;text-align:left;font-size:12px;line-height:1.4;cursor:pointer}.toc button.active{color:var(--qh-color-jade);font-weight:700}.toc .level2{padding-left:9px}.toc .level3{padding-left:18px}
.alchemy-notes{margin-top:58px;color:var(--qh-color-cream)}.alchemy-notes summary{color:var(--qh-color-jade);cursor:pointer}.alchemy-notes>div{position:relative;margin-top:var(--qh-space-3);padding:var(--qh-space-5) var(--qh-space-6);border:1px solid color-mix(in srgb,var(--qh-color-gold) 42%,transparent);background:linear-gradient(90deg,color-mix(in srgb,var(--qh-color-paper) 96%,var(--qh-color-gold)),var(--qh-color-paper) 48%,color-mix(in srgb,var(--qh-color-paper) 95%,var(--qh-color-gold)));box-shadow:var(--qh-shadow-scroll);color:var(--qh-color-paper-ink);line-height:var(--doc-line-height);transform:rotate(.3deg)}.alchemy-notes>div:before,.alchemy-notes>div:after{position:absolute;right:0;left:0;height:8px;content:''}.alchemy-notes>div:before{top:0;background:linear-gradient(var(--qh-color-shadow),transparent)}.alchemy-notes>div:after{bottom:0;background:linear-gradient(transparent,var(--qh-color-shadow))}.pin{position:absolute;top:-8px;left:28px;width:13px;height:13px;border-radius:50%;background:var(--qh-color-jade);box-shadow:0 1px 2px var(--qh-color-shadow)}.seal{position:absolute;right:18px;bottom:14px;display:grid;width:28px;height:28px;place-items:center;border:1px solid var(--qh-color-coral);border-radius:50%;color:var(--qh-color-coral);font-family:var(--qh-font-reading);font-style:normal}
.study-actions{position:fixed;right:50%;bottom:var(--qh-space-5);z-index:5;display:flex;align-items:center;gap:var(--qh-space-2);width:max-content;max-width:calc(100% - 32px);padding:var(--qh-space-2);border:1px solid var(--qh-color-jade-line);border-radius:var(--qh-radius-card-sm);background:var(--qh-color-night-glass);box-shadow:var(--qh-shadow-soft);backdrop-filter:blur(var(--doc-action-blur));transform:translateX(50%)}.study-actions span{padding:0 var(--qh-space-2);color:var(--qh-text-muted);font-size:12px}.study-actions button{padding:8px var(--qh-space-3);border:1px solid transparent;border-radius:var(--qh-radius-stage);color:var(--qh-text);background:transparent;cursor:pointer}.study-actions button:hover{border-color:var(--qh-color-jade-line);color:var(--qh-color-jade);background:var(--qh-color-jade-wash)}
.citation-panel{position:fixed;top:76px;right:var(--qh-space-5);z-index:6;width:min(340px,calc(100vw - 40px));padding:var(--qh-space-6);border:1px solid var(--qh-color-jade-line);border-radius:var(--qh-radius-stage);background:var(--qh-color-night-raised);box-shadow:var(--qh-shadow-deep);backdrop-filter:blur(var(--doc-action-blur));color:var(--qh-text)}.citation-panel>button{position:absolute;top:9px;right:10px;border:0;background:transparent;color:var(--qh-text-muted);font-size:20px;cursor:pointer}.citation-panel p{margin:0 0 5px;color:var(--qh-color-jade);font-size:11px;letter-spacing:1px}.citation-panel h2{margin:0 0 var(--qh-space-5);font:650 18px var(--qh-font-reading)}.citation-panel blockquote{margin:0 0 var(--qh-space-5);padding-left:var(--qh-space-3);border-left:2px solid var(--qh-color-gold);color:var(--qh-text-soft);line-height:var(--doc-line-height)}.citation-panel blockquote small{display:block;margin-bottom:var(--qh-space-2);color:var(--qh-text-muted);font-size:11px}.citation-panel strong{color:var(--qh-color-cream);font-weight:600}.citation-enter-active,.citation-leave-active{transition:opacity var(--doc-citation-duration),transform var(--doc-citation-duration)}.citation-enter-from,.citation-leave-to{opacity:0;transform:translateX(14px)}
@keyframes block-in{from{opacity:0;transform:translateY(var(--doc-reveal-distance))}to{opacity:1;transform:translateY(0)}}
@media(max-width:1020px){.toc{display:none}}@media(max-width:620px){.doc-toolbar{padding:0 var(--qh-space-4)}.document-shell{width:min(var(--doc-measure),calc(100% - 30px));padding-top:48px}.document h1{font-size:30px}.block p,.block li,.table-wrap{font-size:15px}.study-actions{gap:2px}.study-actions span{display:none}.study-actions button{padding:8px}}
@media(prefers-reduced-motion:reduce){.block.is-revealing{animation:none}}
</style>
